import { useState } from 'react';
import {
    Box,
    TextField,
    Button,
    Typography,
    Paper,
    Chip,
} from '@mui/material';
import axios from 'axios';

const endpointMapping = {
    'Notion': 'notion',
    'Airtable': 'airtable',
    'HubSpot': 'hubspot',
};

const miniCardStyle = { p: 2, minWidth: 180, flex: 1 };

export const DataForm = ({ integrationType, credentials, aiMode }) => {
    const [loadedData, setLoadedData] = useState(null);
    const [insights, setInsights] = useState(null);
    const [insightsObj, setInsightsObj] = useState(null);
    const [llmInsights, setLlmInsights] = useState(null);
    const endpoint = endpointMapping[integrationType];

    const handleLoad = async () => {
        try {
            const formData = new FormData();
            formData.append('credentials', JSON.stringify(credentials));
            const response = await axios.post(`http://localhost:8000/integrations/${endpoint}/load`, formData);
            const data = response.data;
            setLoadedData(JSON.stringify(data, null, 2));
            const insightsFormData = new FormData();
            insightsFormData.append('integration_type', integrationType);
            insightsFormData.append('items', JSON.stringify(data));
            const insightsResponse = await axios.post('http://localhost:8000/integrations/insights', insightsFormData);
            setInsights(JSON.stringify(insightsResponse.data, null, 2));
            setInsightsObj(insightsResponse.data);
            setLlmInsights(null);
        } catch (e) {
            alert(e?.response?.data?.detail);
        }
    };

    const handleInsights = async () => {
        try {
            if (!loadedData) {
                alert('Load integration data before generating insights.');
                return;
            }
            const formData = new FormData();
            formData.append('integration_type', integrationType);
            formData.append('items', loadedData);
            const response = await axios.post('http://localhost:8000/integrations/insights', formData);
            setInsights(JSON.stringify(response.data, null, 2));
            setInsightsObj(response.data);
        } catch (e) {
            alert(e?.response?.data?.detail);
        }
    };

    const handleLlmInsights = async () => {
        try {
            if (!loadedData) {
                alert('Load integration data before generating LLM insights.');
                return;
            }
            const formData = new FormData();
            formData.append('integration_type', integrationType);
            formData.append('items', loadedData);
            const response = await axios.post('http://localhost:8000/integrations/insights/llm', formData);
            setLlmInsights(JSON.stringify(response.data, null, 2));
        } catch (e) {
            alert(e?.response?.data?.detail);
        }
    };

    const clearAll = () => {
        setLoadedData(null);
        setInsights(null);
        setInsightsObj(null);
        setLlmInsights(null);
    };

    if (!aiMode) {
        return (
            <Box display='flex' justifyContent='center' alignItems='center' flexDirection='column' width='100%'>
                <Box display='flex' flexDirection='column' width='100%'>
                    <TextField label="Loaded Data" value={loadedData || ''} sx={{mt: 2}} InputLabelProps={{ shrink: true }} disabled />
                    <Button onClick={handleLoad} sx={{mt: 2}} variant='contained'>Load Data</Button>
                    <Button onClick={clearAll} sx={{mt: 1}} variant='contained'>Clear Data</Button>
                </Box>
            </Box>
        );
    }

    return (
        <Box sx={{ width: 'min(1000px, 92vw)', mt: 2 }}>
            <Typography variant='h6' sx={{ mb: 1 }}>AI Insights Dashboard</Typography>
            <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap' }}>
                <Paper elevation={2} sx={miniCardStyle}>
                    <Typography variant='body2'>Integration</Typography>
                    <Typography variant='h6'>{integrationType}</Typography>
                </Paper>
                <Paper elevation={2} sx={miniCardStyle}>
                    <Typography variant='body2'>Health Score</Typography>
                    <Typography variant='h6'>{insightsObj?.health_score ?? 0}/100</Typography>
                </Paper>
                <Paper elevation={2} sx={miniCardStyle}>
                    <Typography variant='body2'>Stale Records</Typography>
                    <Typography variant='h6'>{insightsObj?.stale_items ?? 0}</Typography>
                </Paper>
                <Paper elevation={2} sx={miniCardStyle}>
                    <Typography variant='body2'>Completeness</Typography>
                    <Typography variant='h6'>{insightsObj?.completeness_pct ?? 0}%</Typography>
                </Paper>
                <Paper elevation={2} sx={miniCardStyle}>
                    <Typography variant='body2'>Freshness (30d)</Typography>
                    <Typography variant='h6'>{insightsObj?.freshness_pct ?? 0}%</Typography>
                </Paper>
            </Box>

            <Paper elevation={2} sx={{ p: 2, mt: 2 }}>
                <Typography variant='subtitle1'>Activity Trend (Last 4 Weeks)</Typography>
                <Box sx={{ display: 'flex', alignItems: 'flex-end', gap: 0.5, height: 110, mt: 1 }}>
                    {(insightsObj?.activity_timeline_last_4_weeks || []).map((value, idx) => (
                        <Box key={`activity-${value}-${idx}`} sx={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 0.5 }}>
                            <Typography variant='caption'>{value}</Typography>
                            <Box
                                sx={{
                                    width: 36,
                                    height: `${Math.max(8, Math.min(100, value * 20))}%`,
                                    background: 'linear-gradient(180deg, #ff7f50, #0077B6)',
                                    borderRadius: 0.5,
                                }}
                            />
                            <Typography variant='caption'>W{idx + 1}</Typography>
                        </Box>
                    ))}
                </Box>
            </Paper>
            <Paper elevation={2} sx={{ p: 2, mt: 2 }}>
                <Typography variant='subtitle1'>Age Distribution</Typography>
                <Box sx={{ display: 'flex', alignItems: 'flex-end', gap: 1, height: 110, mt: 1 }}>
                    {Object.entries(insightsObj?.age_buckets || {}).map(([bucket, value]) => (
                        <Box key={`bucket-${bucket}`} sx={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 0.5 }}>
                            <Box
                                sx={{
                                    width: 44,
                                    height: `${Math.max(8, Math.min(100, value * 20))}%`,
                                    background: 'linear-gradient(180deg, #00A86B, #9b5de5)',
                                    borderRadius: 0.5,
                                }}
                            />
                            <Typography variant='caption'>{value}</Typography>
                            <Typography variant='caption'>{bucket}</Typography>
                        </Box>
                    ))}
                </Box>
            </Paper>
            <Paper elevation={2} sx={{ p: 2, mt: 2 }}>
                <Typography variant='subtitle1'>Type Distribution</Typography>
                <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap', mt: 1 }}>
                    {Object.entries(insightsObj?.counts_by_type || {}).map(([key, value]) => (
                        <Chip key={`type-${key}`} label={`${key}: ${value}`} color='primary' variant='outlined' />
                    ))}
                </Box>
            </Paper>
            <Paper elevation={2} sx={{ p: 2, mt: 2 }}>
                <Typography variant='subtitle1'>Recommended Actions</Typography>
                <Box sx={{ mt: 1 }}>
                    {(insightsObj?.recommended_actions || []).map((action, idx) => (
                        <Typography key={`action-${idx}`} variant='body2'>{idx + 1}. {action}</Typography>
                    ))}
                </Box>
            </Paper>

            <Box sx={{ display: 'flex', gap: 1, mt: 2, flexWrap: 'wrap' }}>
                <Button onClick={handleLoad} variant='contained'>Load Data</Button>
                <Button onClick={handleInsights} variant='contained' color='success'>Generate ML Insights</Button>
                <Button onClick={handleLlmInsights} variant='contained' color='secondary'>Generate LLM Insights (Gemini)</Button>
                <Button onClick={clearAll} variant='outlined'>Clear</Button>
            </Box>

            <TextField
                label="Loaded Data (Raw)"
                value={loadedData || ''}
                sx={{mt: 2}}
                InputLabelProps={{ shrink: true }}
                disabled
                multiline
                minRows={5}
                fullWidth
            />
            <TextField
                label="ML Based Insights (Raw)"
                value={insights || ''}
                sx={{mt: 2}}
                InputLabelProps={{ shrink: true }}
                disabled
                multiline
                minRows={5}
                fullWidth
            />
            <TextField
                label="LLM Based Insights (Gemini 2.5 Flash-Lite)"
                value={llmInsights || ''}
                sx={{mt: 2}}
                InputLabelProps={{ shrink: true }}
                disabled
                multiline
                minRows={6}
                fullWidth
            />
        </Box>
    );
};
